-- =============================================================================
-- Migration 20260430000003 — Phase 2a seed data (Bloom & Co.)
--
-- Inserts dummy seed data for the Bloom & Co. dev store into the three
-- Phase 2a tables created in migrations 000000–000002.
--
-- Dev store UUID : 10000000-0000-0000-0000-000000000001
--
-- Seed contents:
--   overhead_categories    —  6 rows   (stable UUIDs 20000000-...-0001 to -0006)
--   overhead_entries       — 144 rows  (6 cats × 12 months × 2 entry types)
--   cash_balance_snapshots —   3 rows  (Feb, Mar, Apr 2026 month-end)
--
-- All INSERTs use ON CONFLICT DO NOTHING for idempotency.
--
-- Overhead totals:
--   Budget : £120,000/month (uniform, all 12 months)
--   Actual : Jan −£1,400 | Feb −£2,600 | Mar +£2,800 | Apr −£800 | May–Dec £0
--
-- Cash balance seed decision (approved):
--   April 30 balance = £186,000 (matches CASH_BALANCE constant in cash-snapshot.ts)
--   cash_runway_months() will return approx 1.55 months (£186k / £119.2k overhead)
--   The 3.4-month mock constant is illustrative and will be replaced when wired.
-- =============================================================================

SET search_path TO public, pg_temp;

-- =============================================================================
-- 1. overhead_categories — 6 rows
--
-- Stable UUIDs allow overhead_entries rows to reference them by ID within
-- this same migration without per-row subqueries.
-- UUID prefix 20000000-... is visually distinct from the store UUID
-- prefix 10000000-... and from random production UUIDs.
-- =============================================================================

INSERT INTO public.overhead_categories
  (id, store_id, name, category_type, is_fixed, sort_order, is_active)
VALUES
  ('20000000-0000-0000-0000-000000000001',
   '10000000-0000-0000-0000-000000000001',
   'Payroll & Contractors', 'payroll', true, 1, true),

  ('20000000-0000-0000-0000-000000000002',
   '10000000-0000-0000-0000-000000000001',
   'Rent & Facilities', 'facilities', true, 2, true),

  ('20000000-0000-0000-0000-000000000003',
   '10000000-0000-0000-0000-000000000001',
   'Software & Tools', 'technology', true, 3, true),

  ('20000000-0000-0000-0000-000000000004',
   '10000000-0000-0000-0000-000000000001',
   'Marketing Fixed', 'marketing_fixed', true, 4, true),

  ('20000000-0000-0000-0000-000000000005',
   '10000000-0000-0000-0000-000000000001',
   'Finance & Legal', 'finance', true, 5, true),

  ('20000000-0000-0000-0000-000000000006',
   '10000000-0000-0000-0000-000000000001',
   'Other Overheads', 'other', true, 6, true)

ON CONFLICT ON CONSTRAINT uq_overhead_categories_store_name DO NOTHING;


